package net.officefloor.hq.app.setting;

/**
 * The settings of a sheet being saved, each null when it is left as it is: the clerk limit with two decimals,
 * "" for no limit, the floor with two decimals, the terms as a whole number of days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" for none, and the period numbering from-date as yyyy-MM-dd, "" for off, and the cap, the proof threshold and the note threshold, each with two decimals, "" for none, and the grace days as a whole number of days, "" for off, and the entry date as yyyy-MM-dd, "" for off.
 * {@code gradeTerms} are the terms of a grade's own being saved, as a whole number of days, by grade (a grade left out is left as it is).
 * {@code gradeGrace} are the grace days of a grade being saved, as a whole number of days, "" for none, by grade (a grade left out is left as it is).
 * {@code gradeProof} are the proof thresholds of a grade being saved, with two decimals, "" for none (the sheet's is in force), by grade (a grade left out is left as it is).
 * {@code perms} are the roles each action is permitted to being saved, by action in {@link Settings#PERM_ACTIONS} order, as a comma separated list, "" for the standing rule.
 * {@code pot} is the pot being saved, with two decimals, "" for none (not dated).
 * {@code parent} is the id of the parent sheet being saved, "" for none (not dated).
 * {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on being saved (not dated).
 * {@code alertThreshold} is the alert threshold being saved, with two decimals, "" for off (not dated).
 * {@code rounding} is the rounding mode being saved, half-up or half-even, "" for none (dated).
 * {@code reviewThreshold} is the review threshold being saved, with two decimals, "" for none (dated).
 * {@code escalateAfter} is the escalation gap being saved, as a whole number of days, "" for off (not dated).
 * {@code reviewSla} is the review SLA being saved, as a whole number of days, "" for none (not dated).
 * {@code proofKinds} are the proof kinds being saved, receipt or photo, comma separated without repeats, "" for none (not dated).
 * {@code from} is the from-date given for a dated setting, by setting key (a key left out is saved from the sheet's today, and audited without one).
 */
public record SheetSettings(String sheetId, String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.SortedMap<String, String> gradeTerms, java.util.SortedMap<String, String> gradeGrace, java.util.Map<String, java.time.LocalDate> from,
        java.util.Map<String, String> perms, java.util.SortedMap<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds) {
}
package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap, the proof threshold and the note threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the entry date (null: left as it is; blank: off, so the sheet's today), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the grace days of a grade, by grade (each left out or null: left as it is; blank: none), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule), and the proof threshold of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's), and the pot (null: left as it is; blank: none), and the parent sheet's id (null: left as it is; blank: none), and the fiscal year start month (null or blank: left as it is), and the alert threshold (null: left as it is; blank: off), and the rounding mode (null: left as it is; blank: none, so the policy date decides), and the review threshold (null: left as it is; blank: none), and the escalation gap in days (null: left as it is; blank: off), and the review SLA in days (null: left as it is; blank: none), and the proof kinds, comma separated (null: left as it is; blank: none). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> gradeGrace, java.util.Map<String, String> from, java.util.Map<String, String> perms,
        java.util.Map<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds) {
}
package net.officefloor.hq.app.setting;

/** The sheet's settings as the screen sees them, each dated one as it is in force on the sheet's today: the clerk limit with two decimals, "" when there is none, the floor with two decimals, the terms in days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" when there is none (the sheet's today is), and the period numbering from-date as yyyy-MM-dd, "" when it is off, and the terms in force for each grade, in days (its own, or the sheet's terms when it has none), and the cap with two decimals, "" when there is none. {@code dated} is every value recorded for each dated setting, by setting key, by from-date. {@code perms} is the roles each action is permitted to, by action, as a comma separated list, "" for the standing rule. {@code graceDays} is the grace days, "" when they are off. {@code entryDate} is the entry date as yyyy-MM-dd, "" when it is off. {@code pot} is the pot with two decimals, "" when there is none. {@code parent} is the parent sheet's id, "" when there is none. {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on. {@code alertThreshold} is the alert threshold with two decimals, "" when alerts are off. {@code escalateAfter} is the escalation gap in days, "" when it is off. {@code reviewSla} is the review SLA in days, "" when there is none. {@code proofKinds} are the proof kinds, comma separated, "" when there are none. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, java.util.List<Settings.DatedValue>> dated,
        java.util.Map<String, String> perms, String graceDays, String entryDate, String pot, String parent, String fiscalStartMonth, String alertThreshold, String escalateAfter, String reviewSla, String proofKinds) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, Settings settings, Sheets sheets,
            ObjectResponse<SettingsResponse> response) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.today(sheet);
        response.send(new SettingsResponse(settings.current(sheet, Settings.CLERK_LIMIT),
                settings.floor(sheet, today).setScale(2).toPlainString(), Integer.toString(settings.terms(sheet, today)),
                settings.latePct(sheet, today).setScale(2).toPlainString(), settings.get(sheet, Settings.POLICY_DATE),
                settings.get(sheet, Settings.PERIOD_NUMBERING_FROM), gradeTerms(settings, sheet, today),
                settings.current(sheet, Settings.CAP), dated(settings, sheet), perms(settings, sheet),
                settings.get(sheet, Settings.GRACE_DAYS), settings.get(sheet, Settings.ENTRY_DATE),
                settings.get(sheet, Settings.POT), settings.parent(sheet),
                Integer.toString(settings.fiscalStartMonth(sheet)), settings.get(sheet, Settings.ALERT_THRESHOLD),
                settings.get(sheet, Settings.ESCALATE_AFTER), settings.get(sheet, Settings.REVIEW_SLA),
                settings.get(sheet, Settings.PROOF_KINDS)));
    }

    private static Map<String, String> gradeTerms(Settings settings, String sheet, LocalDate today) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) {
            terms.put(grade, Integer.toString(settings.terms(sheet, grade, today)));
        }
        return terms;
    }

    private static Map<String, String> perms(Settings settings, String sheet) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : Settings.PERM_ACTIONS) {
            perms.put(action, settings.perm(sheet, action));
        }
        return perms;
    }

    private static Map<String, List<Settings.DatedValue>> dated(Settings settings, String sheet) {
        Map<String, List<Settings.DatedValue>> dated = new LinkedHashMap<>();
        for (String key : Settings.DATED) {
            dated.put(key, settings.history(sheet, key));
        }
        return dated;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Map;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
    private static final Pattern MONTH = Pattern.compile("\\d{1,2}");
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");

    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
    // and only a grade (A, B or C) may have them.
    // A grade's grace days are dated like its terms: blank is none, otherwise a whole number of days, 0 or more, and only for a grade (A, B or C).
    // The period numbering from-date is the same: missing is left as it is, blank is off, otherwise a yyyy-MM-dd date.
    // The cap is missing: left as it is, blank: none, otherwise an amount of 0.00 or more with up to two decimals.
    // The proof threshold is like the cap: missing is left as it is, blank is none, otherwise an amount of 0.00 or more with up to two decimals.
    // A grade's proof threshold is dated like it: blank is none (the sheet's is in force), otherwise an amount like it, and only for a grade (A, B or C).
    // The note threshold is like the cap too.
    // The grace days are missing: left as they are, blank: off, otherwise a whole number of days, 0 or more (not dated).
    // The entry date is like the period numbering from-date: missing is left as it is, blank is off (the sheet's today), otherwise a yyyy-MM-dd date.
    // The pot is like the cap, but not dated: missing is left as it is, blank is none.
    // The alert threshold is like the pot: missing is left as it is, blank is off.
    // The escalation gap is like the grace days: missing is left as it is, blank is off, otherwise a whole number of days, 0 or more (not dated).
    // The proof kinds are not dated: missing is left as they are, blank is none, otherwise receipt or photo, separated by commas.
    // The parent is a sheet id, not dated: missing is left as it is, blank is none. It may not be the sheet itself, nor a
    // sheet that has this one as an ancestor, and it must be a sheet that has been loaded.
    // The rounding mode is dated: missing is left as it is, blank is none (the policy date decides), otherwise half-up or half-even.
    // The fiscal year start month is not dated: missing or blank is left as it is, otherwise a whole month, 1 to 12.
    // An action's permitted roles are missing: left as they are, blank: the standing rule, otherwise clerk or steward, separated by commas.
    // A from-date, given by setting key, is blank (the sheet's today) or a yyyy-MM-dd date, and only a dated setting has one.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
            Sheets sheets, Settings store, Out<SheetSettings> settingsOut) throws InvalidSettingException {
        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
        }
        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
        }
        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
        String fiscalStartMonth = body == null || body.fiscalStartMonth() == null || body.fiscalStartMonth().isBlank() ? null
                : body.fiscalStartMonth().trim();
        if (fiscalStartMonth != null) {
            if (!MONTH.matcher(fiscalStartMonth).matches() || Integer.parseInt(fiscalStartMonth) < 1 || Integer.parseInt(fiscalStartMonth) > 12) {
                throw new InvalidSettingException("The fiscal year start month must be a month, 1 to 12.");
            }
            fiscalStartMonth = Integer.toString(Integer.parseInt(fiscalStartMonth));
        }
        String rounding = body == null || body.rounding() == null ? null : body.rounding().trim();
        if (rounding != null && !rounding.isEmpty() && !Settings.ROUNDING_MODES.contains(rounding)) {
            throw new InvalidSettingException("The rounding mode must be half-up or half-even.");
        }
        String proofKinds = body == null || body.proofKinds() == null ? null : body.proofKinds().trim();
        if (proofKinds != null && !proofKinds.isEmpty()) {
            java.util.List<String> kinds = new java.util.ArrayList<>();
            for (String kind : proofKinds.split(",")) {
                String k = kind.trim();
                if (!net.officefloor.hq.app.claim.ProofRequest.KINDS.contains(k)) {
                    throw new InvalidSettingException("The proof kinds must be receipt or photo, separated by commas.");
                }
                if (!kinds.contains(k)) {
                    kinds.add(k);
                }
            }
            proofKinds = String.join(",", kinds);
        }
        Map<String, LocalDate> from = new java.util.HashMap<>();
        if (body != null && body.from() != null) {
            for (Map.Entry<String, String> entry : body.from().entrySet()) {
                String key = entry.getKey() == null ? "" : entry.getKey().trim();
                String date = entry.getValue() == null ? "" : entry.getValue().trim();
                if (date.isEmpty()) {
                    continue;
                }
                if (!Settings.DATED.contains(key)) {
                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
                }
                try {
                    from.put(key, LocalDate.parse(date));
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
                }
            }
        }
        Map<String, String> perms = new java.util.LinkedHashMap<>();
        if (body != null && body.perms() != null) {
            for (String action : body.perms().keySet()) {
                if (!Settings.PERM_ACTIONS.contains(action)) {
                    throw new InvalidSettingException("Permissions are set only for open, settle, void, reassign, close and reopen.");
                }
            }
            for (String action : Settings.PERM_ACTIONS) {
                String typedRoles = body.perms().get(action);
                if (typedRoles == null) {
                    continue;
                }
                java.util.List<String> roles = new java.util.ArrayList<>();
                if (!typedRoles.isBlank()) {
                    for (String role : typedRoles.split(",")) {
                        String r = role.trim();
                        if (!Settings.ROLES.contains(r)) {
                            throw new InvalidSettingException("The roles allowed to " + action + " must be clerk or steward, separated by commas.");
                        }
                        if (!roles.contains(r)) {
                            roles.add(r);
                        }
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !gradeGrace.isEmpty() || !gradeProof.isEmpty() || !latePct.isEmpty() || policyDate != null
                || numberingFrom != null || cap != null || threshold != null || noteThreshold != null || grace != null || entryDate != null || !perms.isEmpty() || pot != null || parent != null
